const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;

const applyFirstInsuranceSurcharge = (amount: number): number =>
  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;

export const quote = (
  customer: Customer,
  items: Item[],
  contractIndex: number,
): number => {
  const base = items.reduce((sum, item) => sum + basePremium(item), 0);
  return applyFirstInsuranceSurcharge(base) + PROCESSING_FEE;
};
